{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE or replace TABLE goodtribe-wh.maplemonk.shipment_status_mapping ( SHIPPING_STATUS string(16777216), Mapped_Status string(16777216) ); Insert INTO goodtribe-wh.maplemonk.shipment_status_mapping values (\'DELIVERED\',\'Delivered\'),(\'CANCELLED\',\'Cancelled\'),(\'DELIVERED TO ORIGIN\',\'Returned\'),(\'SHIPMENT CREATED\',\'Shipment Created\'),(\'RETURNED\',\'Returned\'),(\'IN TRANSIT\',\'In Transit\'),(\'DELIVERY DELAYED\',\'In Transit\'),(\'DELIVERED TO ORIGIN\',\'RTO\'),(\'CONFIRMED\',\'CONFIRMED\'),(\'IN_TRANSIT\',\'In Transit\'),(\'RTO DELIVERED\',\'RTO\'),(\'CANCELED\',\'Cancelled\'),(\'RTO IN TRANSIT\',\'RTO\'),(\'REACHED AT DESTINATION HUB\',\'In Transit\'),(\'PICKED UP\',\'In Transit\'),(\'UNDELIVERED-2ND ATTEMPT\',\'In Transit\'),(\'RTO_OFD\',\'RTO\'),(\'OUT FOR DELIVERY\',\'Out for delivery\'),(\'RTO INITIATED\',\'RTO\'),(\'PICKUP EXCEPTION\',\'Pickup Error\'),(\'CANCELLATION REQUESTED\',\'Pickup Error\'),(\'READY TO SHIP\',\'Ready to Ship\'),(\'OUT_FOR_DELIVERY\',\'Out for delivery\'),(\'SHIPPED\',\'In Transit\'),(\'PICKUP RESCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-3RD ATTEMPT\',\'In Transit\'),(\'MISROUTED\',\'Misrouted\'),(\'PICKUP SCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-1ST ATTEMPT\',\'In Transit\'),(\'Not Traceble\',\'Pickup Error\'),(\'UNDELIVERED\',\'In Transit\'),(\'LOST\',\'Lost\'),(\'IN TRANSIT-EN-ROUTE\',\'In Transit\'),(\'Indian Speed Post\',\'Indian Speed Post\'),(\'Exception\',\'Exception\'),(\'Shipment Booked\',\'Pickup Error\'),(\'Assigned\',\'Assigned\'),(\'Pending\',\'Pending\'),(\'PrINT\',\'PrINT\'),(\'IN TRANSIT-AT DESTINATION HUB\',\'In Transit\'),(\'Upcoming\',\'Order Yet To sync\'),(\'RTO-In Transit\',\'RTO\'),(\'PICKUP ERROR\',\'Pickup Error\'),(\'RTO-Out for Delivery\',\'RTO\'),(\'RTO-Delivered\',\'RTO\'),(\'OUT FOR PICKUP\',\'Pickup Error\'),(\'RTO_NDR\',\'RTO\'),(\'RTO-Exception\',\'Exception\'),(\'Delayed\',\'In Transit\'),(\'IN TRANSIT-AT SOURCE HUB\',\'In Transit\'),(\'RTS\',\'Underprocess\'),(\'Manifested\',\'Pickup Error\'),(\'Dispatched\',\'In Transit\'),(\'RTO\',\'RTO\'),(\'Not Picked\',\'Pickup Error\'),(\'DAMAGED\',\'Damaged\'),(\'Closed\',\'Cancelled\'),(\'Open\',\'Open\'),(\'On Hold\',\'On Hold\'),(\'Shipped - Returned to Seller\',\'RTO\'),(\'Shipped - Delivered to Buyer\',\'Delivered\'),(\'Shipped - Picked Up\',\'In Transit\'),(\'Shipped - Rejected by Buyer\',\'RTO\'),(\'Shopify_Processed\',\'Shopify_Processed\'),(\'Ready to dispatch\',\'Ready to Dispatch\'),(\'RTO Undelivered\',\'RTO\'),(\'Shipment Lost\',\'Lost\'),(\'Shipment Error\',\'Shipment Error\'),(\'RTO In-Transit\',\'RTO\'),(\'Dispatch / RTO\',\'RTO\'),(\'Pending Pick-up\',\'Pending\'),(\'Dispatch/Intransit\',\'In Transit\'),(\'Dispatch /Lost and Damange\',\'Lost\'),(\'Dispatch /Undelivered\',\'Undelivered\'),(\'Non serviceable\',\'Non Serviceable\'),(\'Not serviceable\',\'Non Serviceable\'),(\'Dispatch/Delivered\',\'Delivered\'),(\'Refund\',\'Refund\'),(\'F&P\',\'F&P\'),(\'SHIPPED - RETURNING TO SELLER\',\'RTO\'),(\'SHIPPED - LOST IN TRANSIT\',\'Lost\'),(\'SHIPPED - DAMAGED\',\'Damaged\'),(\'SHIPPED - OUT FOR DELIVERY\',\'Out for delivery\'); create table if not exists goodtribe-wh.maplemonk.facility_pincode( facility string, pincode string ); create or replace table goodtribe-wh.maplemonk.category_mapping ( category string, final_category string ); INSERT INTO goodtribe-wh.maplemonk.category_mapping (category, final_category) values (\'OST\', \'OST\'), (\'OVERSIZED T-SHIRT\', \'OST\'), (\'JGR\', \'JGR\'), (\'JOGGERS\', \'JGR\'), (\'PNT\', \'PNT\'), (\'PANTS\', \'PNT\'), (\'HST\', \'HST\'), (\'HALF SLEEVE T-SHIRT\', \'HST\'), (\'SHR\', \'SHR\'), (\'SHIRT\', \'SHR\'), (\'HOD\', \'HOD\'), (\'HOODIE\', \'HOD\'), (\'SWT\', \'SWT\'), (\'SWEATSHIRT\', \'SWT\'), (\'COMBO\', \'COMBO\'), (\'COMBOS\', \'COMBO\'), (\'CTP\', \'CTP\'), (\'CROP TOP\', \'CTP\'), (\'TANK TOP\', \'TANK TOP\'), (\'PULLOVER\', \'PULLOVER\'), (\'CO-ORD\', \'CO-ORD\'), (\'VST\', \'VST\'), (\'VEST\', \'VST\'), (\'JKT\', \'JKT\'), (\'JACKET\', \'JKT\'), (\'SRT\', \'SRT\'), (\'SHORTS\', \'SRT\'), (\'FULL SLEEVE T-SHIRT\', \'FULL SLEEVE T-SHIRT\'), (\'GIFT CARDS\', \'GIFT CARDS\'), (\'TRY\', \'TRY\'), (\'T-SHIRT\', \'TRY\'), (\'BDN\', \'BDN\'), (\'BODYCON\', \'BDN\'), (\'TANK BODYCON\', \'TANK BODYCON\'), (\'BXR\', \'BXR\'), (\'BOXER\', \'BXR\'), (\'RNS\', \'RNS\'), (\'RIBBED TOPS\', \'RNS\'), (\'NA\', \'NA\'); CREATE OR REPLACE TABLE goodtribe-wh.maplemonk.marketplace_mapping ( marketplace STRING, final_marketplace STRING ); INSERT INTO goodtribe-wh.maplemonk.marketplace_mapping (marketplace, final_marketplace) VALUES (\'FLIPKART_UNITO\', \'Flipkart\'), (\'LIMEROAD\', \'Limeroad\'), (\'MYNTRAPPMP\', \'Myntra\'), (\'PERSONAL\', \'Personal\'), (\'SHOPIFY\', \'Website\'), (\'AMAZON_PRONK\', \'Amazon\'), (\'POPCLUB\', \'Popclub\'), (\'NYKAA FASHION\', \'Nykaa Fashion\'), (\'NYKAA_FASHION\', \'Nykaa Fashion\'), (\'CUSTOM\', \'Custom\'), (\'AJIO_OMNI\', \'Ajio\'), (\'NYKAA_COM\', \'Nykaa.com\'), (\'STUMBL\', \'Stumbl\'), (\'BEWAKOOF\', \'Bewakoof\'), (\'FLIPKART\', \'Flipkart\'), (\'OFFLINE\', \'Offline\'), (\'AMAZON.IN\', \'Amazon\'), (\'WEBSITE\',\'Website\'); create or replace table goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated_intermediate as select b.customer_id ,case when (upper(b.tags) like \'%APP%\' and upper(b.tags) like \'%IOS%\') then \'APP - IOS\' when (upper(b.tags) like \'%APP%\' and upper(b.tags) like \'%ANDROID%\') then \'APP - ANDROID\' else \'WEBSITE\' end SHOP_NAME ,case when upper(b.tags) like \'%APP%\' then \'APP\' else \'WEBSITE\' end marketplace ,Upper(coalesce(ga4.channel,b.FINAL_UTM_source)) AS CHANNEL ,Upper(coalesce(ga4.final_source,b.FINAL_UTM_channel)) AS SOURCE ,b.ORDER_ID ,order_name reference_code ,b.PHONE ,b.NAME ,b.EMAIL ,coalesce(cast(b.shipping_status_update_date as timestamp),cast(c.shipping_last_update_date as timestamp), cast(d.shipping_last_update_date as timestamp)) AS SHIPPING_LAST_UPDATE_DATE ,b.SKU ,b.PRODUCT_ID ,Upper(b.PRODUCT_NAME) PRODUCT_NAME ,b.CURRENCY ,Upper(b.SHIPPING_CITY) As CITY ,Upper(b.SHIPPING_STATE) AS State ,Upper(b.ORDER_STATUS) ORDER_STATUS ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as date) AS Order_Date ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as datetime) AS Order_Time ,cast(left(c.invoice_date,10) as date) invoice_Date ,b.QUANTITY ,b.GROSS_SALES_BEFORE_TAX AS GROSS_SALES_BEFORE_TAX ,b.DISCOUNT_BEFORE_TAX AS DISCOUNT ,coalesce(c.tax,b.TAX) as tax ,b.SHIPPING_PRICE ,b.TOTAL_SALES AS SELLING_PRICE ,UPPER(coalesce(c.order_status,d.order_status)) as OMS_order_status ,UPPER(coalesce(c.shipping_status, b.shipping_status,d.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(shipmap.final_shipping_status,c.shipping_status, b.shipping_status,d.shipping_status)) FINAL_SHIPPING_STATUS ,cast(b.LINE_ITEM_ID as string) as SALEORDERITEMCODE ,d.sales_order_item_id as SALES_ORDER_ITEM_ID ,coalesce(b.awb,c.awb,d.awb) AWB ,UPPER(REPLACE(IF(ARRAY_LENGTH(GATEWAY) > 0, GATEWAY[OFFSET(0)],\'NA\'), \'\"\', \'\')) PAYMENT_GATEWAY ,upper(coalesce(c.payment_mode,d.payment_mode)) Payment_Mode ,Upper(coalesce(c.Courier,d.courier,b.courier)) AS COURIER ,coalesce(cast(timestamp(b.Shipping_created_at) as date),cast(timestamp(c.manifest_date) as date),cast(timestamp(d.dispatch_date) as date)) AS DISPATCH_DATE ,coalesce(cast(timestamp(c.delivered_date) as date),cast(timestamp(d.delivered_date) as date),case when b.shipping_status like \'delivered\' then cast(timestamp(b.shipping_status_update_date) as date) end) AS DELIVERED_DATE ,case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) AS RETURN_FLAG ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_quantity,0) end returned_quantity ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_value,0) end returned_sales ,case when lower(b.order_status) in (\'cancelled\') then cast(quantity as INT64) end cancelled_quantity ,b.shopify_new_customer_flag as NEW_CUSTOMER_FLAG ,Upper(b.shopify_acquisition_product) as acquisition_product ,cast(case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) in (\'delivered\',\'delivered to origin\') then date_diff(date(b.ORDER_TIMESTAMP),date(coalesce(cast(b.shipping_status_update_date as timestamp),cast(c.shipping_last_update_date as timestamp), cast(d.shipping_last_update_date as timestamp))),day) when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) in (\'in transit\', \'shipment created\') then date_diff(date(b.ORDER_TIMESTAMP), CURRENT_DATE(),day) end as INT64) as Days_in_Shipment ,b.shopify_acquisition_date AS MARKETPLACE_ACQUISITION_DATE ,b.SKU_CODE ,UPPER(b.PRODUCT_NAME_FINAL) PRODUCT_NAME_FINAL ,UPPER(coalesce(cm.final_category,b.PRODUCT_CATEGORY)) PRODUCT_CATEGORY ,upper(b.PRODUCT_SUB_CATEGORY) PRODUCT_SUB_CATEGORY ,b.SKU_CODE commonsku ,upper(coalesce(c.warehouse_name,d.warehouse_name)) WAREHOUSE ,coalesce(b.pincode,d.pincode,c.pincode) as pincode ,coalesce(c.pickup_pincode,fa.pincode) as source_pincode ,b.discount_codes ,b.rto_tag_customer ,b.tags order_tag ,b.stage ,b.predicted_date ,case when m.orderno is not null then 1 when c.shipping_Status in (\'RTO INITIATED\', \'RTO IN-TRANSIT\', \'DELIVERED TO ORIGIN\', \'RETURNED\') then 1 else 0 end as rto_flag_new ,case when lower(c.order_Status) = \'returned\' and lower(c.shipping_Status) = \'delivered\' then 1 else 0 end as dto_flag ,cogs ,c.invoice_number from goodtribe-wh.maplemonk.goodtribe_wh_SHOPIFY_FACT_ITEMS b left join ( select transactionid, final_source, channel from maplemonk.goodtribe_wh_GA_ORDER_BY_SOURCE_CONSOLIDATED qualify row_number() over (partition by transactionid order by 1) =1 ) GA4 on replace(b.order_name,\'#\',\'\') = replace(GA4.transactionid, \'#\',\'\') left join (select * from ( select * ,row_number()over(partition by reference_code, Marketplace_LineItem_ID order by last_update_date desc) rw from goodtribe-wh.maplemonk.goodtribe_wh_EasyEcom_FACT_ITEMS ) z where z.rw = 1 and lower(marketplace) like any (\'%shopify%\') ) c on replace(b.order_name,\'#\',\'\') = c.reference_code and b.LINE_ITEM_ID=c.Marketplace_LineItem_ID left join (select * from (select * ,row_number() over (partition by order_id, SPLIT(saleorderitemcode, \'-\')[OFFSET(0)] order by shipping_last_update_date desc) rw from goodtribe-wh.maplemonk.goodtribe_wh_UNICOMMERCE_FACT_ITEMS where lower(marketplace) like any (\'%shopify%\')) where rw=1 ) d on b.order_id=d.order_id and b.line_item_id=SPLIT(saleorderitemcode, \'-\')[OFFSET(0)] left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from goodtribe-wh.maplemonk.facility_pincode ) where rw = 1 ) fa on lower(d.warehouse_name) = lower(fa.facility) left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from goodtribe-wh.maplemonk.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(b.shipping_status,c.shipping_status,d.shipping_status,b.ORDER_STATUS)) = lower(ShipMap.shipping_status) LEFT JOIN goodtribe-wh.maplemonk.category_mapping cm on upper(cm.category) = upper(b.product_category) left join ( select distinct orderno from goodtribe-wh.maplemonk.amazon_s3_goodtribe_rto_s3 ) m on replace(b.ordeR_name, \'#\', \'\') = m.orderno ; CREATE OR REPLACE TABLE goodtribe-wh.maplemonk.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, email, contact_num, 19700000000 + dense_rank() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, email, phone phone FROM goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated_intermediate where phone is not null ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, coalesce(p.maple_monk_id,pe.maple_monk_id) maple_monk_id FROM ( SELECT phone AS contact_num, email FROM goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) LEFT JOIN (select * from new_phone_numbers qualify row_number() over (partition by lower(email) order by 1) = 1) pe ON lower(pe.email) = lower(e.email) ) b ) ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') and rto_flag_new = 0 THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, iso.iso_code as state_iso_code, m.*, safe_divide(mc.spend, count(*) over (partition by m.order_date order by 1)) spend FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM goodtribe-wh.maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM goodtribe-wh.maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN (select * from maplemonk.Google_sheets_Location_ISO) iso ON lower(replace(iso.state,\' \',\'\')) = lower(replace(m.state,\' \',\'\')) left join ( select date, sum(spend) spend from goodtribe-wh.maplemonk.goodtribe_wh_MARKETING_CONSOLIDATED group by 1 ) mc on m.order_Date = mc.date ; ALTER TABLE goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_rto STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_sku STRING, ADD COLUMN acquisition_category STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING, ADD COLUMN acquisition_shopname STRING; UPDATE goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated AS A SET A.new_customer_flag_rto = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, first_complete_order_date, CASE WHEN Order_Date <= first_complete_order_date THEN \'New\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated where rto_flag_new = 0 and lower(order_status) <> \'cancelled\' ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, channel, shop_name AS shop_name, marketplace as marketplace, FROM (SELECT * FROM( SELECT customer_id_final, order_date, channel, shop_name, marketplace, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated AS a SET a.acquisition_shopname = b.shop_name FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; CREATE OR replace temporary TABLE temp_sku_1 AS SELECT customer_id_final, sku FROM ( SELECT customer_id_final, order_date, sku, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated AS A SET A.acquisition_sku = TRIM(SPLIT(B.sku, \'-\')[OFFSET(0)]) FROM ( SELECT * FROM temp_sku_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; CREATE OR REPLACE TEMPORARY TABLE temp_category_1 AS SELECT customer_id_final, product_category, FROM (SELECT * FROM( SELECT customer_id_final, order_date, product_category, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated AS a SET a.acquisition_category = b.product_category FROM temp_category_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\') THEN \'DADRA AND NAGAR HAVELI\' WHEN UPPER(state) IN (\'DD\', \'DAMAN AND DIU\') THEN \'DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) = \'LADAKH\' THEN \'LADAKH\' ELSE state END WHERE UPPER(state) IN ( \'AP\', \'AR\', \'AS\', \'BR\', \'CT\', \'GA\', \'GJ\', \'HR\', \'HP\', \'JH\', \'KA\', \'KL\', \'MP\', \'MH\', \'MN\', \'ML\', \'MZ\', \'NL\', \'OR\', \'PB\', \'RJ\', \'SK\', \'TN\', \'TS\', \'TL\', \'TR\', \'UP\', \'UT\', \'UK\', \'WB\', \'AN\', \'CH\', \'DN\', \'DD\', \'LD\', \'DL\', \'PY\', \'JK\', \'JAMMU & KASHMIR\', \'ANDAMAN & NICOBAR ISLANDS\' ); CREATE TABLE IF NOT EXISTS goodtribe-wh.maplemonk.goodtribe_wh_easyecom_returns_intermediate ( ORDER_ID INT64, INVOICE_ID INT64, SUBORDER_ID STRING, REFERENCE_CODE STRING, CREDIT_NOTE_ID INT64, ORDER_DATE TIMESTAMP, INVOICE_DATE TIMESTAMP, RETURN_DATE TIMESTAMP, MANIFEST_DATE TIMESTAMP, IMPORT_DATE TIMESTAMP, LAST_UPDATE_DATE TIMESTAMP, COMPANY_PRODUCT_ID STRING, PRODUCTNAME STRING, PRODUCT_ID STRING, SKU STRING, MARKETPLACE STRING, MARKETPLACE_ID INT64, REPLACEMENT_ORDER INT64, RETURN_REASON STRING, RETURNED_QUANTITY FLOAT64, RETURN_AMOUNT_WITHOUT_TAX FLOAT64, RETURN_TAX FLOAT64, RETURN_SHIPPING_CHARGE FLOAT64, RETURN_MISC FLOAT64, TOTAL_RETURN_AMOUNT FLOAT64 ); CREATE OR REPLACE TABLE goodtribe-wh.maplemonk.goodtribe_wh_easyecom_returns_fact_items AS SELECT IFNULL(FE.Source, \'NA\') AS Marketing_CHANNEL, FR.* FROM goodtribe-wh.maplemonk.goodtribe_wh_easyecom_returns_intermediate FR LEFT JOIN ( SELECT DISTINCT REPLACE(reference_code, \'#\', \'\') AS REFERENCE_CODE, Source FROM goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated ) FE ON FR.REFERENCE_CODE = FE.REFERENCE_CODE; CREATE TABLE IF NOT EXISTS goodtribe-wh.maplemonk.goodtribe_wh_unicommerce_returns_intermediate ( MARKETPLACE STRING, SOURCE STRING, ORDER_ID STRING, REFERENCE_CODE STRING, PHONE STRING, NAME STRING, EMAIL STRING, ORDER_DATE TIMESTAMP, RETURN_DISPLAYCODE STRING, RETURN_STATUS STRING, INVENTORY_RECEIVED_DATE TIMESTAMP, RETURN_COMPLETE_DATE TIMESTAMP, RETURN_INVOICE_DISPLAY_CODE STRING, RETURN_COURIER STRING, RETURN_PROVIDER_SHIPPING_STATUS STRING, RETURN_TRACKING_NUMBER STRING, RETURN_TYPE STRING, sale_order_item_code STRING, ITEMSKU STRING, ITEM_NAME STRING, INVENTORY_TYPE STRING ); CREATE OR REPLACE TABLE goodtribe-wh.maplemonk.goodtribe_wh_unicommerce_returns_fact_items AS SELECT IFNULL(FE.channel, \'NA\') AS Marketing_CHANNEL, FE.quantity AS RETURNED_QUANTITY, FE.selling_price AS TOTAL_RETURN_AMOUNT, FE.tax AS RETURN_TAX, FE.selling_price - FE.tax AS RETURN_AMOUNT_WITHOUT_TAX, FR.* FROM (select * from goodtribe-wh.maplemonk.goodtribe_wh_unicommerce_returns_intermediate where RETURN_DISPLAYCODE is not null) FR LEFT JOIN ( SELECT REPLACE(reference_code, \'#\', \'\') AS REFERENCE_CODE, SALEORDERITEMCODE, channel, Source, SUM(quantity) AS quantity, SUM(selling_price) AS Selling_price, SUM(tax) AS tax FROM goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated GROUP BY REFERENCE_CODE, SALEORDERITEMCODE, channel, Source ) FE ON FR.REFERENCE_CODE = FE.REFERENCE_CODE AND FR.sale_order_item_code = FE.SALEORDERITEMCODE; create or replace table goodtribe-wh.maplemonk.goodtribe_wh_RETURNS_CONSOLIDATED as select CAST(fi.return_approved_at AS DATETIME) AS RETURN_DATE, UPPER(sc.CHANNEL) AS Marketing_channel, UPPER(sc.marketplace) as marketplace, CAST(fi.return_request_type AS STRING) AS RETURN_TYPE, SUM(fi.returned_quantity) AS TOTAL_RETURNED_QUANTITY, SUM(ifnull(coalesce(fi.refunded_amount,er.Total_Credit_Note_Amount),0)) AS TOTAL_RETURN_AMOUNT, SUM(ifnull(fi.total_tax,0)) AS TOTAL_RETURN_TAX, SUM(ifnull(coalesce(fi.refunded_amount,er.Total_Credit_Note_Amount),0) - ifnull(fi.total_tax,0)) AS TOTAL_RETURN_AMOUNT_EXCL_TAX from goodtribe-wh.maplemonk.goodtribe_RETURNSPRIME_CONSOLIDATED fi LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER( PARTITION BY reference_code,saleorderitemcode)rw FROM goodtribe-wh.maplemonk.goodtribe_wh_sales_consolidated ) WHERE rw=1 )sc ON fi.order_name = sc.reference_code AND fi.order_item_id = sc.saleorderitemcode LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER( PARTITION BY reference_code,saleorderitemcode)rw FROM goodtribe-wh.maplemonk.easyecom_goodtribe_all_returns ) WHERE rw=1 ) er ON fi.order_name = er.reference_code AND fi.order_item_id = er.saleorderitemcode WHERE UPPER(fi.return_request_type) =\'RETURN\' group by 1,2,3,4 ;",
                    "transaction": true
                }
            ) }}
